import re

def split_claims(answer):
    claims = []
    for sentence in re.split(r'(?<=[.!?])\s+', answer.strip()):
        cites = re.findall(r'\[(S\d+)\]', sentence)
        text = re.sub(r'\s*\[S\d+\]', '', sentence).strip()
        if text:
            claims.append({'text': text, 'cites': cites})
    return claims

def check_citations(claims, corpus_ids, retrieved_ids):
    labels = []
    for c in claims:
        cites = set(c['cites'])
        if not cites:
            labels.append('UNCITED')
        elif not cites <= set(corpus_ids):
            labels.append('NOT_IN_CORPUS')
        elif not cites <= set(retrieved_ids):
            labels.append('NOT_RETRIEVED')
        else:
            labels.append('OK')
    return labels

