from collections import Counter

def abstention_rates(rows):
    unans = [ab for ok, ab in rows if not ok]
    ans = [ab for ok, ab in rows if ok]
    rate = lambda xs: sum(xs) / len(xs) if xs else 0.0
    return (rate(unans), rate(ans))

def cohen_kappa(a, b):
    n = len(a)
    po = sum(x == y for x, y in zip(a, b)) / n
    ca, cb = Counter(a), Counter(b)
    pe = sum(ca[k] * cb[k] for k in set(a) | set(b)) / (n * n)
    if pe == 1:
        return 1.0
    return (po - pe) / (1 - pe)
